1	//! A pure-`std` reimplementation of the `sortedcontainers` C++ header.
2	//!
3	//! The layout follows the C++ library of the same name (itself a port of Python's
4	//! `sortedcontainers`): entries are held in a two-level list of buckets rather than in a
5	//! search tree, so ordered lookups are `O(log n)` while insertion and removal shift
6	//! elements within a single bucket instead of across the whole collection.
7	//!
8	//! * [`sorted_map`] — [`SortedMap`], the public container.
9	//! * [`cursor`] — [`Cursor`], the stand-in for a C++ iterator.
10	//! * `buckets` — the storage engine, private because the two-level layout is an
11	//!   implementation detail that no caller should be able to observe.
12	
13	// This module is a library: it deliberately offers the whole container API, and re-exports
14	// all of it, even though the program in `test18.rs` exercises only part of it.
15	#![allow(dead_code, unused_imports)]
16	
17	mod buckets;
18	pub mod cursor;
19	pub mod sorted_map;
20	
21	pub use self::cursor::Cursor;
22	pub use self::sorted_map::SortedMap;
23	
24	/// Copies every entry of `source` into `target`, overwriting keys that already exist.
25	///
26	/// Mirrors the free function `sortedcontainers::update(target, source)`, whose
27	/// last-write-wins behaviour the original program depends on.
28	pub fn update<K, V>(target: &mut SortedMap<K, V>, source: &SortedMap<K, V>)
29	where
30	    K: Ord + Clone,
31	    V: Clone,
32	{
33	    for (key, value) in source.iter() {
34	        target.insert(key.clone(), value.clone());
35	    }
36	}
37	
38	#[cfg(test)]
39	mod tests {
40	    use super::*;
41	
42	    #[test]
43	    fn update_merges_and_overwrites() {
44	        let mut target: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
45	        for key in 0..6 {
46	            target.insert((key, key * 2), format!("value_{}", key));
47	        }
48	        let mut source: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
49	        for key in 4..9 {
50	            source.insert((key, key * 2), format!("other_{}", key));
51	        }
52	
53	        update(&mut target, &source);
54	
55	        assert_eq!(target.len(), 9);
56	        // Keys only in `target` keep their value; overlapping keys take `source`'s.
57	        assert_eq!(target.get(&(3, 6)).map(String::as_str), Some("value_3"));
58	        assert_eq!(target.get(&(4, 8)).map(String::as_str), Some("other_4"));
59	        assert_eq!(target.get(&(8, 16)).map(String::as_str), Some("other_8"));
60	        assert_eq!(source.len(), 5, "the source must be left untouched");
61	    }
62	
63	    #[test]
64	    fn update_from_an_empty_source_is_a_no_op() {
65	        let mut target: SortedMap<i32, i32> = SortedMap::new();
66	        target.insert(1, 1);
67	        update(&mut target, &SortedMap::new());
68	        assert_eq!(target.len(), 1);
69	    }
70	}
